//! Fixed-coin known answers and independent arithmetic and decryption vectors of RNS-BGV.
//!
//! Two independent references check every word the implementation produces:
//!
//! 1. `tests/vectors/bgv_kat_v1.txt`, generated by the Python reference
//!    `tests/vectors/bgv_reference.py` from a master seed: profile identity,
//!    operation seeds, the secret key, the public and switching keys, fresh
//!    ciphertexts and the result, public noise bound, exact noise and
//!    plaintext of every homomorphic operation.
//! 2. The `num-bigint` oracle of `tests/support`, which recomputes the same
//!    pipeline at run time for the pinned seeds and for further seeds and
//!    chain shapes.
//!
//! Neither reference shares code with `iroha_fhe`: both work on integers
//! modulo the full modulus and re-implement the coin derivation and samplers.
// TODO: parity with a third-party BGV implementation on shared parameters has not been
// run. Both references here were written for this crate.
mod support;

use iroha_fhe::bgv::{
    BgvCandidate, BgvParameters, BgvProfile, Ciphertext, EvaluationKeys, KeySet, NoiseBound,
    Plaintext, PublicKey, SecretKey, SwitchingKey, SwitchingKeyKind,
    fixtures::{self, FixtureEntropy},
};
use num_bigint::{BigInt, Sign};
use support::{
    kat::{Kat, Section},
    oracle::{Oracle, OracleCiphertext, fixture_seed, lift, words},
};

fn natural_to_bigint(value: &iroha_fhe::natural::Natural) -> BigInt {
    let bytes: Vec<u8> = value
        .words_le()
        .iter()
        .flat_map(|word| word.to_le_bytes())
        .collect();
    BigInt::from_bytes_le(Sign::Plus, &bytes)
}

/// The oracle's view of a profile: plain numbers only.
fn oracle_of(profile: &BgvProfile) -> Oracle {
    let parameters = profile.parameters();
    Oracle {
        log_degree: parameters.log_degree,
        degree: parameters.degree(),
        t: parameters.plaintext_modulus,
        main: parameters.main_primes.clone(),
        main_roots: parameters.main_roots.clone(),
        special: parameters.special_primes.clone(),
        special_roots: parameters.special_roots.clone(),
        digit_primes: parameters.digit_primes,
        eta: parameters.error_eta,
    }
}

/// Compare one production ciphertext with an expectation of words, bound and plaintext.
fn check_ciphertext(
    label: &str,
    profile: &BgvProfile,
    oracle: &Oracle,
    keys: &KeySet,
    ciphertext: &Ciphertext,
    expected: &OracleCiphertext,
) {
    assert_eq!(ciphertext.level(), expected.level, "{label}: level");
    assert_eq!(
        ciphertext.component_count(),
        expected.components.len(),
        "{label}: components"
    );
    assert_eq!(
        ciphertext.canonical_words(),
        oracle.ciphertext_words(expected),
        "{label}: words"
    );
    assert_eq!(
        natural_to_bigint(ciphertext.noise_bound().as_natural()),
        expected.bound,
        "{label}: bound"
    );
    let secret = fixtures::secret_coefficients(&keys.secret);
    let plaintext = keys.secret.decrypt(profile, ciphertext).expect("decrypt");
    assert_eq!(
        plaintext.coefficients(),
        oracle.decrypt(&secret, expected),
        "{label}: plaintext"
    );
    // The exact noise, computed by the oracle from the production words, is within the bound.
    let noise = oracle.exact_noise(&secret, expected);
    assert!(
        noise <= expected.bound,
        "{label}: noise {noise} above the bound"
    );
    assert!(
        expected.bound <= oracle.capacity(expected.level),
        "{label}: capacity"
    );
    // The production inner product is the oracle's, residue for residue.
    let inner = fixtures::inner_product_words(profile, &keys.secret, ciphertext).expect("inner");
    let lifted = lift(&inner, &oracle.main[..=expected.level]);
    let modulus = oracle.modulus(expected.level);
    let centered: Vec<BigInt> = lifted
        .iter()
        .map(|value| support::oracle::centered(value, &modulus))
        .collect();
    assert_eq!(
        centered,
        oracle.inner(&secret, expected),
        "{label}: inner product"
    );
}

/// The keys of a section decode from the words the Python reference pinned, and their
/// byte frames are the documented layout of those words.
fn check_key_codecs(profile: &BgvProfile, keys: &KeySet, section: &Section<'_>, element: u32) {
    let frame = |header: &[u8], words: &[u64]| -> Vec<u8> {
        let mut bytes = profile.identity().to_vec();
        bytes.extend_from_slice(header);
        bytes.extend(words.iter().flat_map(|word| word.to_le_bytes()));
        bytes
    };
    // Public key: identity, then `b` and `a`.
    let public_words = section.words("public_key");
    let public = PublicKey::from_canonical_words(profile, &public_words).expect("public key");
    assert_eq!(public, keys.public);
    let public_frame = keys.public.to_bytes(profile).expect("frame");
    assert_eq!(public_frame, frame(&[], &public_words));
    assert_eq!(PublicKey::from_bytes(profile, &public_frame), Ok(public));
    // Switching keys: identity, kind tag, element, then the digits.
    let relinearization_words = section.words("relinearization_key");
    let relinearization = SwitchingKey::from_canonical_words(
        profile,
        SwitchingKeyKind::Relinearization,
        &relinearization_words,
    )
    .expect("relinearization key");
    assert_eq!(&relinearization, keys.evaluation.relinearization());
    let relinearization_frame = relinearization.to_bytes(profile).expect("frame");
    assert_eq!(
        relinearization_frame,
        frame(&[0, 0, 0, 0, 0], &relinearization_words)
    );
    let galois_words = section.words("galois_key");
    let galois = SwitchingKey::from_canonical_words(
        profile,
        SwitchingKeyKind::Galois(element),
        &galois_words,
    )
    .expect("galois key");
    assert_eq!(Some(&galois), keys.evaluation.galois(element));
    let mut galois_header = vec![1_u8];
    galois_header.extend_from_slice(&element.to_le_bytes());
    let galois_frame = galois.to_bytes(profile).expect("frame");
    assert_eq!(galois_frame, frame(&galois_header, &galois_words));
    // Evaluation keys: the two frames in order, and back.
    let evaluation =
        EvaluationKeys::from_keys(profile, relinearization, [galois]).expect("evaluation keys");
    assert_eq!(evaluation, keys.evaluation);
    let evaluation_frame = evaluation.to_bytes(profile).expect("frame");
    assert_eq!(
        evaluation_frame,
        [relinearization_frame, galois_frame].concat()
    );
    assert_eq!(
        EvaluationKeys::from_bytes(profile, &evaluation_frame),
        Ok(evaluation)
    );
    // Secret key: identity, then two bits per pinned coefficient, low bits first.
    let coefficients = section.signed("secret");
    let mut custody = profile.identity().to_vec();
    for group in coefficients.chunks(4) {
        custody.push(
            group
                .iter()
                .enumerate()
                .fold(0_u8, |byte, (position, &value)| {
                    let code = match value {
                        0 => 0_u8,
                        1 => 1,
                        -1 => 2,
                        other => panic!("the reference pinned a non-ternary coefficient {other}"),
                    };
                    byte | (code << (2 * position))
                }),
        );
    }
    let exported = keys
        .secret
        .to_custody_bytes(profile)
        .expect("custody frame");
    assert_eq!(exported.as_slice(), custody.as_slice());
    let restored = SecretKey::from_custody_bytes(profile, exported).expect("secret key");
    assert_eq!(fixtures::secret_coefficients(&restored), coefficients);
}

fn master_of(section: &Section<'_>) -> [u8; 64] {
    section.bytes("master_seed").try_into().expect("64 bytes")
}

/// Run the pinned pipeline of one known-answer section through the implementation.
fn check_section(name: &str, shape: (u32, u64, (u32, usize), (u32, usize), usize)) {
    let kat = Kat::load();
    let section = kat.section(name);
    let (log_degree, plaintext_modulus, main, special, digit_primes) = shape;
    assert_eq!(u64::from(log_degree), section.number("log_degree"));
    assert_eq!(plaintext_modulus, section.number("plaintext_modulus"));
    assert_eq!(digit_primes as u64, section.number("digit_primes"));
    let parameters =
        BgvParameters::derive(log_degree, plaintext_modulus, main, special, digit_primes)
            .expect("parameters");
    // Primes, roots and the identity are those of the Python reference.
    assert_eq!(parameters.main_primes, section.numbers("main_primes"));
    assert_eq!(parameters.main_roots, section.numbers("main_roots"));
    assert_eq!(parameters.special_primes, section.numbers("special_primes"));
    assert_eq!(parameters.special_roots, section.numbers("special_roots"));
    let profile = BgvProfile::new(parameters).expect("profile");
    assert_eq!(profile.identity().as_slice(), section.bytes("identity"));
    let oracle = oracle_of(&profile);
    assert_eq!(&oracle.identity(), profile.identity());
    let master = master_of(&section);
    let mut entropy = FixtureEntropy::new(master);
    assert_eq!(entropy.seed(0).as_slice(), section.bytes("seed0"));
    assert_eq!(entropy.seed(0), fixture_seed(&master, 0));
    let element = u32::try_from(section.number("galois_element")).expect("element");
    let keys = fixtures::key_set(&profile, &[element], &mut entropy).expect("keys");
    // Keys.
    assert_eq!(
        fixtures::secret_coefficients(&keys.secret),
        section.signed("secret")
    );
    assert_eq!(
        keys.public.canonical_words(&profile).expect("words"),
        section.words("public_key")
    );
    let relinearization = keys.evaluation.relinearization();
    assert_eq!(
        relinearization.canonical_words(&profile).expect("words"),
        section.words("relinearization_key")
    );
    let galois = keys.evaluation.galois(element).expect("galois key");
    assert_eq!(galois.kind(), SwitchingKeyKind::Galois(element));
    assert_eq!(
        galois.canonical_words(&profile).expect("words"),
        section.words("galois_key")
    );
    check_key_codecs(&profile, &keys, &section, element);
    // Ciphertexts and operations.
    let pinned = |label: &str| -> OracleCiphertext {
        let level = usize::try_from(section.number(&format!("{label}_level"))).expect("level");
        let canonical = section.words(&format!("{label}_words"));
        let components = canonical.len() / ((level + 1) * profile.degree());
        oracle.ciphertext(
            level,
            components,
            &canonical,
            section.integer(&format!("{label}_bound")),
        )
    };
    let check = |label: &str, ciphertext: &Ciphertext| {
        let expected = pinned(label);
        check_ciphertext(label, &profile, &oracle, &keys, ciphertext, &expected);
        let secret = fixtures::secret_coefficients(&keys.secret);
        assert_eq!(
            oracle.exact_noise(&secret, &expected),
            section.integer(&format!("{label}_noise")),
            "{label}: exact noise"
        );
        assert_eq!(
            oracle.decrypt(&secret, &expected),
            section.numbers(&format!("{label}_plain")),
            "{label}: pinned plaintext"
        );
    };
    let message1 = section.numbers("message1");
    let message2 = section.numbers("message2");
    let plain1 = Plaintext::new(&profile, message1).expect("plaintext");
    let plain2 = Plaintext::new(&profile, message2).expect("plaintext");
    let ct1 = fixtures::encrypt(&profile, &keys.public, &plain1, &mut entropy).expect("ct1");
    let ct2 = fixtures::encrypt(&profile, &keys.public, &plain2, &mut entropy).expect("ct2");
    assert_eq!(u64::from(entropy.draws()), section.number("draws"));
    check("ct1", &ct1);
    check("ct2", &ct2);
    check("sum", &profile.add(&ct1, &ct2).expect("sum"));
    check("difference", &profile.sub(&ct1, &ct2).expect("difference"));
    check(
        "plain_sum",
        &profile.add_plain(&ct1, &plain2).expect("plain sum"),
    );
    check(
        "plain_product",
        &profile.mul_plain(&ct1, &plain2).expect("plain product"),
    );
    let tensor = profile.tensor(&ct1, &ct2).expect("tensor");
    check("tensor", &tensor);
    let relinearized = profile
        .relinearize(&tensor, relinearization)
        .expect("relinearized");
    check("relinearized", &relinearized);
    let switched = profile.switch_down(&relinearized).expect("switched");
    check("switched", &switched);
    let rotated = profile.apply_galois(&switched, galois).expect("rotated");
    check("rotated", &rotated);
    check(
        "lowest",
        &profile.switch_to_level(&rotated, 0).expect("lowest"),
    );
    check(
        "square",
        &profile
            .multiply(&switched, &switched, relinearization)
            .expect("square"),
    );
    // The canonical frame of every pinned ciphertext round-trips.
    for ciphertext in [&ct1, &tensor, &switched] {
        let bytes = ciphertext.to_bytes(&profile).expect("bytes");
        assert_eq!(
            bytes.len(),
            Ciphertext::encoded_len(&profile, ciphertext.level(), ciphertext.component_count())
                .expect("length")
        );
        assert_eq!(
            Ciphertext::from_bytes(&profile, &bytes).as_ref(),
            Ok(ciphertext)
        );
    }
}

#[test]
fn toy_chain_reproduces_the_python_known_answers() {
    check_section("toy16", (4, 257, (30, 5), (31, 2), 2));
}

#[test]
fn fifty_and_sixty_bit_chain_reproduces_the_python_known_answers() {
    check_section("wide8", (3, 257, (50, 6), (60, 2), 2));
}

#[test]
fn fully_splitting_modulus_reproduces_the_python_known_answers() {
    check_section("split16", (4, 97, (40, 4), (41, 2), 1));
}

/// Run a full pipeline from a master seed and compare every step with the oracle.
fn check_against_oracle(profile: &BgvProfile, master: [u8; 64], elements: &[u32]) {
    let oracle = oracle_of(profile);
    assert_eq!(&oracle.identity(), profile.identity());
    let mut entropy = FixtureEntropy::new(master);
    let keys = fixtures::key_set(profile, elements, &mut entropy).expect("keys");
    // The oracle derives the same keys from the same seeds.
    let secret = oracle.secret(&fixture_seed(&master, 0));
    assert_eq!(fixtures::secret_coefficients(&keys.secret), secret);
    let public = oracle.public_key(&fixture_seed(&master, 1), &secret);
    let mut public_words = words(&public.0, &oracle.main);
    public_words.extend(words(&public.1, &oracle.main));
    assert_eq!(
        keys.public.canonical_words(profile).expect("words"),
        public_words
    );
    let full = oracle.full_primes();
    let key_words = |key: &support::oracle::OracleSwitchingKey| -> Vec<u64> {
        key.iter()
            .flat_map(|(b, a)| {
                let mut flat = words(b, &full);
                flat.extend(words(a, &full));
                flat
            })
            .collect()
    };
    let relinearization = oracle.switching_key(&fixture_seed(&master, 2), &secret, 0);
    assert_eq!(
        keys.evaluation
            .relinearization()
            .canonical_words(profile)
            .expect("words"),
        key_words(&relinearization)
    );
    // Galois keys are generated in the order given; a repeated element is generated once.
    let mut galois = Vec::new();
    let mut seen = Vec::new();
    for &element in elements {
        if seen.contains(&element) {
            continue;
        }
        let draw = 3 + u32::try_from(seen.len()).expect("draw");
        seen.push(element);
        let key = oracle.switching_key(&fixture_seed(&master, draw), &secret, element);
        assert_eq!(
            keys.evaluation
                .galois(element)
                .expect("key")
                .canonical_words(profile)
                .expect("words"),
            key_words(&key),
            "galois {element}"
        );
        galois.push((element, key));
    }
    let degree = profile.degree();
    let t = profile.plaintext_modulus();
    let message = |tag: u64| -> Vec<u64> {
        (0..degree as u64)
            .map(|index| (index * index * 7 + index * tag + tag * 13 + 1) % t)
            .collect()
    };
    let first_encryption = 3 + u32::try_from(seen.len()).expect("draw");
    let (message1, message2) = (message(3), message(8));
    let plain1 = Plaintext::new(profile, message1.clone()).expect("plaintext");
    let plain2 = Plaintext::new(profile, message2.clone()).expect("plaintext");
    let ct1 = fixtures::encrypt(profile, &keys.public, &plain1, &mut entropy).expect("ct1");
    let ct2 = fixtures::encrypt(profile, &keys.public, &plain2, &mut entropy).expect("ct2");
    let expected1 = oracle.encrypt(&fixture_seed(&master, first_encryption), &public, &message1);
    let expected2 = oracle.encrypt(
        &fixture_seed(&master, first_encryption + 1),
        &public,
        &message2,
    );
    let check = |label: &str, ciphertext: &Ciphertext, expected: &OracleCiphertext| {
        check_ciphertext(label, profile, &oracle, &keys, ciphertext, expected);
    };
    check("ct1", &ct1, &expected1);
    check("ct2", &ct2, &expected2);
    check(
        "sum",
        &profile.add(&ct1, &ct2).expect("sum"),
        &oracle.add(&expected1, &expected2),
    );
    check(
        "difference",
        &profile.sub(&ct1, &ct2).expect("difference"),
        &oracle.sub(&expected1, &expected2),
    );
    let worst = Plaintext::worst_case_bound(profile);
    check(
        "plain sum",
        &profile.add_plain(&ct1, &plain2).expect("plain sum"),
        &oracle.add_plain(&expected1, &message2, worst.linf),
    );
    check(
        "plain product",
        &profile.mul_plain(&ct1, &plain2).expect("plain product"),
        &oracle.mul_plain(&expected1, &message2, worst.l1),
    );
    // Multiply at every level that has room, switching both operands down in between.
    let mut current = (ct1, expected1);
    let mut other = (ct2, expected2);
    loop {
        let level = current.0.level();
        let tensor = profile.tensor(&current.0, &other.0);
        let expected_tensor = oracle.tensor(&current.1, &other.1);
        if expected_tensor.bound > oracle.capacity(level) {
            assert_eq!(
                tensor.err(),
                Some(iroha_fhe::bgv::BgvError::NoiseBudgetExceeded { level })
            );
            break;
        }
        let tensor = tensor.expect("tensor");
        check(
            &format!("tensor at level {level}"),
            &tensor,
            &expected_tensor,
        );
        let product = profile
            .relinearize(&tensor, keys.evaluation.relinearization())
            .expect("relinearized");
        let expected_product = oracle.relinearize(&expected_tensor, &relinearization);
        check(
            &format!("product at level {level}"),
            &product,
            &expected_product,
        );
        for (element, key) in &galois {
            let rotated = profile
                .apply_galois(&product, keys.evaluation.galois(*element).expect("key"))
                .expect("rotated");
            check(
                &format!("galois {element} at level {level}"),
                &rotated,
                &oracle.apply_galois(&expected_product, *element, key),
            );
        }
        if level == 0 {
            break;
        }
        let switched = profile.switch_down(&product).expect("switched");
        let expected_switched = oracle.switch_down(&expected_product);
        check(
            &format!("switch from level {level}"),
            &switched,
            &expected_switched,
        );
        let lowered = profile.switch_down(&other.0).expect("lowered");
        let expected_lowered = oracle.switch_down(&other.1);
        check(
            &format!("operand below level {level}"),
            &lowered,
            &expected_lowered,
        );
        current = (switched, expected_switched);
        other = (lowered, expected_lowered);
    }
}

fn master(tag: u8) -> [u8; 64] {
    std::array::from_fn(|index| {
        tag.wrapping_mul(41)
            .wrapping_add(u8::try_from(index).expect("index below 64").wrapping_mul(7))
    })
}

#[test]
fn seeded_pipelines_match_the_oracle_on_several_chain_shapes() {
    // (log N, t, main, special, digit size): partial digits, single-prime digits, three-prime
    // digits with three special primes, 60-bit main primes, and a batching modulus.
    let shapes = [
        (
            4_u32,
            257_u64,
            (30_u32, 5_usize),
            (31_u32, 2_usize),
            2_usize,
        ),
        (3, 257, (50, 7), (60, 2), 2),
        (3, 257, (50, 6), (60, 3), 3),
        (4, 97, (40, 5), (41, 2), 1),
        (2, 257, (60, 4), (61, 3), 2),
        (5, 65_537, (55, 4), (60, 2), 2),
    ];
    for (index, (log_degree, plaintext_modulus, main, special, digit_primes)) in
        shapes.into_iter().enumerate()
    {
        let parameters =
            BgvParameters::derive(log_degree, plaintext_modulus, main, special, digit_primes)
                .expect("parameters");
        let profile = BgvProfile::new(parameters).expect("profile");
        let order = 2_u32 << log_degree;
        for seed_tag in 0..2_u8 {
            check_against_oracle(
                &profile,
                master(seed_tag * 16 + u8::try_from(index).expect("few shapes") + 1),
                &[3, order - 1, 3, 5],
            );
        }
    }
}

#[test]
fn explicit_coins_match_the_oracle_equations() {
    let profile =
        BgvProfile::new(BgvParameters::derive(3, 257, (50, 4), (60, 2), 2).expect("parameters"))
            .expect("profile");
    let oracle = oracle_of(&profile);
    let degree = profile.degree();
    // Coins chosen by formula, not sampled: the equations must hold for any coins in range.
    let signed_degree = i64::try_from(degree).expect("small degree");
    let secret: Vec<i64> = (0..signed_degree)
        .map(|index| (index * 2 + 1) % 3 - 1)
        .collect();
    let error = |tag: i64| -> Vec<i64> {
        (0..signed_degree)
            .map(|index| (index * 5 + tag * 3) % 43 - 21)
            .collect()
    };
    let mask_words = |tag: u64, primes: &[u64]| -> Vec<u64> {
        primes
            .iter()
            .enumerate()
            .flat_map(|(limb, &prime)| {
                (0..degree as u64).map(move |index| {
                    (index + 1)
                        .wrapping_mul(0x9E37_79B9_7F4A_7C15)
                        .wrapping_add(tag * 1_000_003 + limb as u64)
                        % prime
                })
            })
            .collect()
    };
    let key = fixtures::secret_key_from_coefficients(&profile, &secret).expect("secret");
    let public_mask = mask_words(1, &oracle.main);
    let public =
        fixtures::public_key_from_coins(&profile, &key, &public_mask, &error(1)).expect("public");
    let oracle_a = lift(&public_mask, &oracle.main);
    let oracle_public = (
        oracle.public_key_from_coins(&secret, &oracle_a, &error(1)),
        oracle_a,
    );
    let mut expected_words = words(&oracle_public.0, &oracle.main);
    expected_words.extend(words(&oracle_public.1, &oracle.main));
    assert_eq!(
        public.canonical_words(&profile).expect("words"),
        expected_words
    );
    let full = oracle.full_primes();
    for (kind, tag) in [
        (SwitchingKeyKind::Relinearization, 0_u32),
        (SwitchingKeyKind::Galois(3), 3),
        (SwitchingKeyKind::Galois(15), 15),
    ] {
        let coins: Vec<(Vec<u64>, Vec<i64>)> = (0..profile.digit_count() as u64)
            .map(|digit| {
                (
                    mask_words(10 + digit + u64::from(tag), &full),
                    error(i64::try_from(digit).expect("few digits") + 2),
                )
            })
            .collect();
        let switching =
            fixtures::switching_key_from_coins(&profile, &key, kind, &coins).expect("key");
        let oracle_coins: Vec<(Vec<BigInt>, Vec<i64>)> = coins
            .iter()
            .map(|(mask, error)| (lift(mask, &full), error.clone()))
            .collect();
        let expected: Vec<u64> = oracle
            .switching_key_from_coins(&secret, tag, &oracle_coins)
            .iter()
            .flat_map(|(b, a)| {
                let mut flat = words(b, &full);
                flat.extend(words(a, &full));
                flat
            })
            .collect();
        assert_eq!(
            switching.canonical_words(&profile).expect("words"),
            expected,
            "{kind:?}"
        );
    }
    let message: Vec<u64> = (0..degree as u64)
        .map(|index| (index * 100 + 200) % 257)
        .collect();
    let plaintext = Plaintext::new(&profile, message.clone()).expect("plaintext");
    let mask: Vec<i64> = (0..signed_degree).map(|index| index % 3 - 1).collect();
    let ciphertext =
        fixtures::encrypt_from_coins(&profile, &public, &plaintext, &mask, &error(7), &error(9))
            .expect("ciphertext");
    let expected = oracle.encrypt_from_coins(&oracle_public, &message, &mask, &error(7), &error(9));
    assert_eq!(
        ciphertext.canonical_words(),
        oracle.ciphertext_words(&expected)
    );
    assert_eq!(oracle.decrypt(&secret, &expected), message);
    assert_eq!(
        key.decrypt(&profile, &ciphertext)
            .expect("plaintext")
            .coefficients(),
        message
    );
}

/// Identities of the pinned candidates, computed by `tests/vectors/bgv_reference.py`.
const CANDIDATE_IDENTITIES: [(BgvCandidate, &str); 3] = [
    (
        BgvCandidate::AffineF257,
        "3ab33fd9d135717b5fb830fd7a5515c8a378e09496d9ea4c9560c4d3961bf1b0",
    ),
    (
        BgvCandidate::BoundedF257,
        "a218a403aa48ae5b17e8a22e2f0bb68698e549ca58cdadc3c40352f198f7b20e",
    ),
    (
        BgvCandidate::RefreshF257,
        "87ee13ea7b82f543bf9bdf1b2b90d4180b64338fb76878d3c49fb5d6ae3c4a7e",
    ),
];

#[test]
fn candidate_identities_are_the_pinned_ones() {
    assert_eq!(
        CANDIDATE_IDENTITIES.map(|(candidate, _)| candidate),
        BgvCandidate::ALL
    );
    for (candidate, expected) in CANDIDATE_IDENTITIES {
        let identity =
            candidate
                .parameters()
                .identity()
                .iter()
                .fold(String::new(), |mut text, byte| {
                    use std::fmt::Write as _;
                    write!(text, "{byte:02x}").expect("writing to a string");
                    text
                });
        assert_eq!(identity, expected, "{}", candidate.name());
    }
}

#[test]
fn affine_candidate_encrypts_evaluates_and_decrypts_at_full_size() {
    // N = 2^14 with the pinned 50 and 60-bit primes. The oracle multiplies by Kronecker
    // substitution here, so this also checks the transforms at production size.
    let profile = BgvProfile::candidate(BgvCandidate::AffineF257).expect("profile");
    let oracle = oracle_of(&profile);
    assert_eq!(&oracle.identity(), profile.identity());
    let master = master(77);
    let mut entropy = FixtureEntropy::new(master);
    let secret = fixtures::secret_key(&profile, &mut entropy).expect("secret");
    let public = fixtures::public_key(&profile, &secret, &mut entropy).expect("public");
    let oracle_secret = oracle.secret(&fixture_seed(&master, 0));
    assert_eq!(fixtures::secret_coefficients(&secret), oracle_secret);
    let oracle_public = oracle.public_key(&fixture_seed(&master, 1), &oracle_secret);
    let mut public_words = words(&oracle_public.0, &oracle.main);
    public_words.extend(words(&oracle_public.1, &oracle.main));
    assert_eq!(
        public.canonical_words(&profile).expect("words"),
        public_words
    );
    let degree = profile.degree();
    let message: Vec<u64> = (0..degree as u64)
        .map(|index| (index * 31 + 7) % 257)
        .collect();
    let plaintext = Plaintext::new(&profile, message.clone()).expect("plaintext");
    let ciphertext = fixtures::encrypt(&profile, &public, &plaintext, &mut entropy).expect("ct");
    let expected = oracle.encrypt(&fixture_seed(&master, 2), &oracle_public, &message);
    assert_eq!(
        ciphertext.canonical_words(),
        oracle.ciphertext_words(&expected)
    );
    assert_eq!(
        secret
            .decrypt(&profile, &ciphertext)
            .expect("plaintext")
            .coefficients(),
        message
    );
    // Exact noise of a fresh ciphertext at full size against the public bound.
    let noise = oracle.exact_noise(&oracle_secret, &expected);
    let bound = natural_to_bigint(profile.fresh_noise());
    assert_eq!(bound, oracle.fresh_noise());
    assert!(noise <= bound);
    // Switching down to level zero keeps the plaintext and matches the oracle word for word.
    let lowest = profile.switch_to_level(&ciphertext, 0).expect("lowest");
    let mut expected_lowest = expected;
    while expected_lowest.level > 0 {
        expected_lowest = oracle.switch_down(&expected_lowest);
    }
    assert_eq!(
        lowest.canonical_words(),
        oracle.ciphertext_words(&expected_lowest)
    );
    assert_eq!(
        natural_to_bigint(lowest.noise_bound().as_natural()),
        expected_lowest.bound
    );
    assert_eq!(
        secret
            .decrypt(&profile, &lowest)
            .expect("plaintext")
            .coefficients(),
        message
    );
    // A claimed bound is carried through the canonical words.
    let rebuilt = Ciphertext::from_canonical_words(
        &profile,
        0,
        2,
        &lowest.canonical_words(),
        &NoiseBound::new(lowest.noise_bound().as_natural().clone()),
    )
    .expect("rebuilt");
    assert_eq!(rebuilt, lowest);
}
